syntaxCard.syntax:
for i in 序列:
    if 提前结束的条件:
        break          # 立即终止本层整个循环
    if 跳过本轮的条件:
        continue       # 跳过本轮剩余语句，直接进入下一轮
    其余语句
else:
    循环没有被 break 打断时执行

codeDemo.code:
# ① break 与 continue 的区别
for i in range(1, 10):
    if i == 3:
        continue
    if i == 6:
        break
    print(i, end=" ")
print()

# ② for-else：51~59 中第一个 7 的倍数
for n in range(51, 60):
    if n % 7 == 0:
        print("找到了：", n)
        break
else:
    print("没找到")

# ③ while 中 continue：更新必须放在前面
i = 0
while i < 5:
    i += 1
    if i % 2 == 0:
        continue
    print(i, end=" ")
print()

# ④ 嵌套：break 只跳一层
for i in range(1, 4):
    for j in range(1, 4):
        if j == 2:
            break
        print(f"({i},{j})", end=" ")
    print("<- 外层第", i, "轮结束")

