# ① 九九乘法表（下三角，5 行）
n = 5
for i in range(1, n + 1):
    row = []
    for j in range(1, i + 1):
        row.append(f"{j}*{i}={j * i}")
    print("\t".join(row))

# ② 星号直角三角形与倒三角形
