cautionBox.wrongCode:
# 错误 1：内层用了 end=""，却没有在内层结束后补换行
for i in range(1, 4):
    for j in range(1, i + 1):
        print("*", end="")

# 错误 2：内外层用了同一个变量 i
for i in range(1, 4):
    for i in range(1, 4):
        print("*", end="")
    print("第", i, "行")      # 永远显示第 3 行

cautionBox.rightCode:
for i in range(1, 4):
    for j in range(1, i + 1):
        print("*", end="")
    print()                  # 一行结束，补换行

for i in range(1, 4):
    for j in range(1, 4):
        print("*", end="")
    print("第", i, "行")      # i 没有被内层覆盖

workedExamples.code:
s = input()
k = int(input())

# ① 凯撒加密：只处理小写字母，空格原样保留
cipher = ""
for ch in s:
    if "a" <= ch <= "z":
        cipher += chr((ord(ch) - ord("a") + k) % 26 + ord("a"))
    else:
        cipher += ch
print(cipher)

# ② 九九乘法表前 n 行
n = int(input())
for i in range(1, n + 1):
    for j in range(1, i + 1):
        print(f"{j}*{i}={j * i}", end="\t")
    print()

